// Validate webhook secret
const headers = $input.first().json.headers || {};
const secret = headers['x-webhook-secret'] || headers['X-Webhook-Secret'] || '';
const expectedSecret = 'aegisai-n8n-secret';

if (secret !== expectedSecret) {
  throw new Error('Unauthorized: invalid webhook secret');
}

// Extract body — n8n puts JSON body here
const body = $input.first().json.body || $input.first().json;

const phone      = body.phone || body.to || '';
const userName   = body.userName || body.user_name || 'there';
const taskTitle  = body.taskTitle || body.task_title || 'your task';
const taskId     = body.taskId || body.task_id || '';
const riskScore  = body.riskScore || body.risk_score || 0;
const severity   = body.severity || 'critical';
const alertType  = body.alertType || 'Deadline Risk Alert';

const message = body.message ||
  `Hello ${userName}. This is FocusGuard AI. ` +
  `Your task '${taskTitle}' is at ${riskScore} percent risk of being missed. ` +
  `Would you like me to generate an emergency focus schedule? Say yes or no.`;

return [{
  json: {
    phone,
    userName,
    taskTitle,
    taskId,
    riskScore,
    severity,
    alertType,
    message,
    timestamp: new Date().toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' })
  }
}];
